package com.artie.heart.gateway

import io.swagger.v3.core.util.Json
import io.swagger.v3.core.util.Json31
import io.swagger.v3.oas.models.OpenAPI
import io.swagger.v3.oas.models.Operation
import io.swagger.v3.oas.models.SpecVersion
import io.swagger.v3.parser.OpenAPIV3Parser
import io.swagger.v3.parser.core.models.ParseOptions

/**
 * An operation as the gateway uses it: its name (the operationId), title and
 * doc, and the HEART relation it is. A description generated by a HEART
 * server names that relation (`x-heart-relation`); otherwise it is named
 * after the operation's id, `switchOff` as `switch-off`.
 */
class SpecOperation(val name: String, val title: String, val doc: String, val relation: String)

/**
 * An act: its operation, its segment under `/actions/`, its input's JSON Schema, every `$ref` resolved (a
 * DELETE's from its query parameters), and the [method] it is served by.
 */
class SpecAct(val operation: SpecOperation, val path: String, val schema: String, val method: String = "POST")

/** A search: its operation, and what its `name` and `id` parameters are. */
class SpecSearch(val operation: SpecOperation, val nameDescription: String, val idDescription: String)

/** One collection the upstream serves, with what can be done to its members and at the bookmark. */
class SpecType(
    val collection: String,
    val noun: String,
    val read: SpecOperation,
    val search: SpecSearch?,
    val acts: List<SpecAct>,
    val bookmarkActs: List<SpecAct>,
)

/** A parameter of an operation: its name, where it goes (`path` or `query`), its words and its JSON Schema. */
class SpecParameter(val name: String, val location: String, val description: String, val schema: Map<String, Any>)

/**
 * An operation where it is served: its method, its path template, its parameters, its JSON body's schema,
 * and the schema of its JSON answer when it succeeds.
 */
class SpecRoute(
    val operation: SpecOperation,
    val method: String,
    val path: PathTemplate,
    val parameters: List<SpecParameter>,
    val body: Map<String, Any>?,
    val response: Map<String, Any>? = null,
)

/**
 * The upstream's OpenAPI 3.x description, read by the conventions every
 * HEART binding's twin follows: `/{collection}/{id}` reads a member,
 * `/{collection}` searches, `/{collection}/{id}/actions/{path}` acts on a
 * member and `/actions/{path}` acts at the bookmark, tagged with its
 * collection. Deprecated operations are left out: they are former paths.
 *
 * With [include], only the operations it names are read, and the rest of the
 * description is left out before it is parsed: GitHub's is 13.5 MB, and a
 * connector uses a few of its operations. Every operation read is a [route],
 * whatever its path, for a connector's resource files to name.
 */
class GatewaySpec(text: String, include: Set<OperationId>? = null) {
    private val api: OpenAPI = OpenAPIV3Parser()
        .readContents(Slice.of(text, include), null, ParseOptions().apply { isResolve = true; isResolveFully = true })
        .let { read -> checkNotNull(read.openAPI) { "the upstream's description is unreadable: ${read.messages}" } }

    val title: String = api.info?.title ?: "Upstream"
    val doc: String = api.info?.description ?: title

    private val mapper = if (api.specVersion == SpecVersion.V31) Json31.mapper() else Json.mapper()

    /** Every operation read, by its id. */
    val routes: Map<OperationId, SpecRoute> = api.paths.orEmpty().flatMap { (path, item) ->
        item.readOperationsMap().map { (method, operation) -> route(path, method.name, operation) }
    }.associateBy { it.operation.name }

    /** The operation [id], or a refusal naming it. */
    fun route(id: OperationId): SpecRoute = routes[id] ?: error("the upstream's description has no operation $id")

    /** Each (path, method, operation) the gateway can use. */
    private val operations = api.paths.orEmpty().flatMap { (path, item) ->
        item.readOperationsMap().map { (method, operation) -> Triple(path, method.name, operation) }
    }.filter { (_, _, operation) -> operation.deprecated != true }

    val types: List<SpecType> = operations.mapNotNull { (path, method, _) ->
        READ.matchEntire(path)?.groupValues?.get(1)?.takeIf { method == "GET" }
    }.distinct().map { type(it) }

    private fun type(collection: String): SpecType {
        val read = operation(single("GET", "/$collection/{id}") ?: error("no read of /$collection/{id}"))
        val search = single("GET", "/$collection")?.let { found ->
            val parameters = found.parameters.orEmpty().associateBy { it.name }
            SpecSearch(
                operation(found),
                parameters["name"]?.description ?: "Part of the name",
                parameters["id"]?.description ?: "The id",
            )
        }
        val acts = operations.mapNotNull { (path, method, operation) ->
            ACT.matchEntire(path)?.takeIf { method in ACT_METHODS && it.groupValues[1] == collection }
                ?.let { act(operation, it.groupValues[2], method) }
        }
        val bookmarkActs = operations.mapNotNull { (path, method, operation) ->
            val tag = operation.tags.orEmpty().firstOrNull()
            BOOKMARK_ACT.matchEntire(path)?.takeIf { method == "POST" && tag == collection }
                ?.let { act(operation, it.groupValues[1]) }
        }
        val noun = read.name.removePrefix("get").replaceFirstChar { it.lowercase() }.ifEmpty { collection }
        return SpecType(collection, noun, read, search, acts, bookmarkActs)
    }

    /** The one operation of [method] at [path], whatever its id parameter is named. */
    private fun single(method: String, path: String): Operation? = operations.firstOrNull { (at, m, _) ->
        m == method && at.replace(PARAMETER, "{id}") == path
    }?.third

    /** An act served by [method]: its input is its JSON (or JSON Merge Patch) body, or a DELETE's query. */
    private fun act(operation: Operation, path: String, method: String = "POST"): SpecAct {
        val content = operation.requestBody?.content
        val body = (content?.get(JSON) ?: content?.get(MERGE_PATCH))?.schema
        val schema = if (method == "DELETE") queryInput(operation) else body?.let { mapper.writeValueAsString(it) }
        return SpecAct(operation(operation), path, schema ?: "{}", method)
    }

    /** The schema of a DELETE's input: one property per query parameter, required as the parameter is. */
    private fun queryInput(operation: Operation): String? {
        val query = operation.parameters.orEmpty().filter { it.`in` == "query" }
        if (query.isEmpty()) return null
        val properties = query.associate { it.name to plain(it.schema).orEmpty() }
        val required = query.filter { it.required == true }.map { it.name }
        return mapper.writeValueAsString(
            mapOf("type" to "object", "properties" to properties) +
                (if (required.isEmpty()) emptyMap() else mapOf("required" to required)),
        )
    }

    private fun route(path: String, method: String, operation: Operation): SpecRoute {
        val parameters = operation.parameters.orEmpty().map { parameter ->
            val schema = plain(parameter.schema).orEmpty()
            SpecParameter(parameter.name, parameter.`in`, parameter.description.orEmpty(), schema)
        }
        val body = plain(operation.requestBody?.content?.get(JSON)?.schema)
        val response = plain(operation.responses?.get("200")?.content?.get(JSON)?.schema)
        return SpecRoute(operation(operation), method, path, parameters, body, response)
    }

    /** A schema as plain JSON values. */
    @Suppress("UNCHECKED_CAST")
    private fun plain(schema: Any?): Map<String, Any>? =
        schema?.let { mapper.convertValue(it, Map::class.java) as Map<String, Any> }

    private fun operation(operation: Operation): SpecOperation {
        val name = checkNotNull(operation.operationId) { "an operation has no operationId: ${operation.summary}" }
        // The first paragraph is what the act does; the rest, such as when it is allowed, the gateway learns per state.
        val doc = operation.description?.substringBefore("\n\n")?.trim()?.ifEmpty { null }
        val relation = (operation.extensions?.get(RELATION) as? String)?.substringAfter(':') ?: relationOf(name)
        return SpecOperation(name, operation.summary ?: name, doc ?: operation.summary ?: name, relation)
    }

    private companion object {
        const val JSON = "application/json"
        const val MERGE_PATCH = "application/merge-patch+json"

        /** The methods an act is served by; a GET reads. */
        val ACT_METHODS = setOf("POST", "PUT", "PATCH", "DELETE")

        /** The extension a HEART server's description names each operation's relation in. */
        const val RELATION = "x-heart-relation"
        val PARAMETER = Regex("\\{[^}/]+}")
        val READ = Regex("^/([^/{}]+)/\\{[^}/]+}$")
        val ACT = Regex("^/([^/{}]+)/\\{[^}/]+}/actions/([^/{}]+)$")
        val BOOKMARK_ACT = Regex("^/actions/([^/{}]+)$")
    }
}
